{
    "name": "057_residual_coupling_flow_block",
    "hf_id": "myshell-ai/OpenVoice",
    "description": "Residual coupling block for normalizing flow with affine coupling transformations. Splits channels in half, transforms one half conditioned on the other, and combines. Supports forward and reverse passes for flow-based generative modeling.",
    "axes": {
        "batch_size": {
            "type": "var",
