            "type": "const",
            "value": 192,
            "description": "Total number of channels (must be even)"
        },
        "hidden_channels": {
            "type": "const",
            "value": 192,
            "description": "Hidden channels in transformation network"
        },
        "half_channels": {
            "type": "const",
            "value": 96,
            "description": "Half of total channels for splitting"
        },
